/**
 * 购买链接类型
 */
interface PurchaseLink {
  id: string;
  platform: string;
  url: string;
}

/**
 * 产品数据类型
 */
interface ProductData {
  id: string;
  name: string;
  nameEn: string;
  slug: string;
  description: string;
  price: number;
  capacity?: string;
  purchaseUrl?: string;
  purchaseLinks?: PurchaseLink[];
  images: { url: string; alt?: string }[];
  category: { name: string };
  ingredients?: string;
  usage?: string;
  benefits: string[];
  allowDirectBuy?: boolean;
  stock?: number;
}

interface ProductDrawerProps {
  /** 是否打开 */
  isOpen: boolean;
  /** 关闭回调 */
  onClose: () => void;
  /** 产品数据 */
  product: ProductData | null;
}

